import numpy as np

def main():
    N, P = map(int, input().split())
    # Stirling numbers of the second kind mod P
    S = [[0] * (N + 1) for _ in range(N + 1)]
    S[0][0] = 1
    for r in range(1, N + 1):
        for j in range(1, r + 1):
            S[r][j] = (S[r - 1][j - 1] + j * S[r - 1][j]) % P
    # c[r][j] = S(r,j) * (-1)^{j+1}
    crow = [None] * (N + 1)
    for r in range(1, N + 1):
        arr = np.zeros(N + 1, dtype=np.int64)
        for j in range(1, r + 1):
            if j % 2 == 1:
                arr[j] = S[r][j] % P
            else:
                arr[j] = (P - S[r][j]) % P
        crow[r] = arr
    # pw[e][j] = 2^{e*j} mod P
    pwrow = [None] * (N + 1)
    for e in range(N + 1):
        step = pow(2, e, P)
        arr = np.zeros(N + 1, dtype=np.int64)
        t = 1
        for j in range(N + 1):
            arr[j] = t
            t = t * step % P
        pwrow[e] = arr
    # Binomials mod P
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P
    H = [0] * (N + 1)
    H[0] = 1
    for n in range(1, N + 1):
        total = 0
        for r in range(1, n + 1):
            e = n - r
            inner = int(((crow[r][1:r + 1] * pwrow[e][1:r + 1]) % P).sum() % P)
            total = (total + C[n][r] * inner % P * H[e]) % P
        H[n] = total
    ans = 0
    for n in range(N + 1):
        ans = (ans + C[N][n] * H[n]) % P
    print(ans % P)

main()

