    t = inp.split()
    n = int(t[0])
    p = int(t[1])
    start = tuple([0] * n)
    seen = {start}
    stack = [start]
    # All nonempty subsets S, represented as bitmasks over positions 0..n-1.
    # Operation with subset S sets x = sum of 2^(i-1) for i in S, i.e. x = mask
    # where bit (i) corresponds to position i (0-indexed).
    while stack:
        cur = stack.pop()
        for mask in range(1, 1 << n):
            nxt = tuple(mask if (mask >> i) & 1 else cur[i] for i in range(n))
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return str(len(seen) % p)
